export const accessRules=sqliteTable('access_rules',{id:text('id').primaryKey(),subjectType:text('subject_type').notNull(),subjectId:text('subject_id').notNull(),department:text('department').notNull(),page:text('page').notNull(),action:text('action').notNull(),effect:text('effect').notNull(),scope:text('scope').notNull(),tenantId:text('tenant_id').notNull().default('procus')},t=>[uniqueIndex('access_rule_subject_action').on(t.tenantId,t.subjectType,t.subjectId,t.department,t.page,t.action)]);

export const researchCloudJobs=sqliteTable('research_cloud_jobs',{recordingId:text('recording_id').primaryKey().references(()=>researchRecordings.id),providerId:text('provider_id').unique(),tokenHash:text('token_hash').notNull(),state:text('state').notNull(),leaseUntil:integer('lease_until').notNull().default(0),attempts:integer('attempts').notNull().default(0)});

