// ── Identity & platform ──────────────────────────────────────────────────────
// A person is one global identity; each workspace they belong to has a membership row in `members`.
// `tenant_id` is the workspace key throughout the schema.
export const identities=sqliteTable('identities',{id:text('id').primaryKey(),email:text('email').notNull().unique(),username:text('username').unique(),name:text('name').notNull(),lastMemberId:text('last_member_id'),createdAt:text('created_at').notNull()});
