export const knowledgeTaxonomy=sqliteTable('knowledge_taxonomy',{id:text('id').primaryKey(),tenantId:text('tenant_id').notNull(),kind:text('kind').notNull(),name:text('name').notNull(),definition:text('definition').notNull().default(''),parentId:text('parent_id'),synonymsJson:text('synonyms_json').notNull().default('[]'),retentionDays:integer('retention_days'),status:text('status').notNull().default('active'),origin:text('origin').notNull().default('human'),proposedBy:text('proposed_by').notNull(),approvedBy:text('approved_by'),createdAt:text('created_at').notNull(),updatedAt:text('updated_at').notNull()},t=>[uniqueIndex('knowledge_taxonomy_name').on(t.tenantId,t.kind,t.name)]);
export const knowledgeReviews=sqliteTable('knowledge_reviews',{id:text('id').primaryKey(),tenantId:text('tenant_id').notNull(),knowledgeId:text('knowledge_id').notNull(),reason:text('reason').notNull(),detail:text('detail').notNull().default(''),assigneeId:text('assignee_id'),status:text('status').notNull().default('open'),dueAt:text('due_at'),outcome:text('outcome').notNull().default(''),resolvedBy:text('resolved_by'),resolvedAt:text('resolved_at'),createdAt:text('created_at').notNull()},t=>[index('knowledge_reviews_open').on(t.tenantId,t.status,t.assigneeId)]);
export const knowledgeQuestions=sqliteTable('knowledge_questions',{id:text('id').primaryKey(),tenantId:text('tenant_id').notNull(),askerId:text('asker_id').notNull(),title:text('title').notNull(),body:text('body').notNull().default(''),department:text('department').notNull().default(''),status:text('status').notNull().default('unanswered'),acceptedAnswerId:text('accepted_answer_id'),escalatedTo:text('escalated_to').notNull().default(''),visibility:text('visibility').notNull().default('company'),articleId:text('article_id'),createdAt:text('created_at').notNull(),updatedAt:text('updated_at').notNull()},t=>[index('knowledge_questions_status').on(t.tenantId,t.status)]);
export const knowledgeAnswers=sqliteTable('knowledge_answers',{id:text('id').primaryKey(),tenantId:text('tenant_id').notNull(),questionId:text('question_id').notNull(),kind:text('kind').notNull(),body:text('body').notNull(),citationsJson:text('citations_json').notNull().default('[]'),confidence:real('confidence'),authorId:text('author_id').notNull(),status:text('status').notNull().default('published'),helpful:integer('helpful').notNull().default(0),notHelpful:integer('not_helpful').notNull().default(0),correctionsJson:text('corrections_json').notNull().default('[]'),createdAt:text('created_at').notNull()},t=>[index('knowledge_answers_question').on(t.tenantId,t.questionId)]);
export const knowledgeSearches=sqliteTable('knowledge_searches',{id:text('id').primaryKey(),tenantId:text('tenant_id').notNull(),memberId:text('member_id').notNull(),query:text('query').notNull(),filtersJson:text('filters_json').notNull().default('{}'),saved:integer('saved').notNull().default(0),name:text('name').notNull().default(''),createdAt:text('created_at').notNull()},t=>[index('knowledge_searches_member').on(t.tenantId,t.memberId,t.createdAt)]);
